from analysis.Cx_annulirostris.determine_subtypes.process import make_msa_seq_matrix, find_differences_between_subtype_and_all_others, find_Cx_annulirostris_frag_position_in_ref
import polars as pl
    
def find_Ae_notoscriptus_cluster_defining_snps(msa_path: str, fragment_metadata: str, reference_path:str, reference_contig:str, tmp_dir:str, ignore_clusters:list=None) -> pl.DataFrame:
    # parse msa - should have been generated by tree code
    seq_matrix, ids = make_msa_seq_matrix(msa_path)
    # parse subtypes fragment metadata to get subtype information for each fragment
    fragment_metadata = pl.read_csv(fragment_metadata, separator='\t')
    fragment_metadata = fragment_metadata.rename({"seq_id": "fasta_id", "cluster_id": "subtype"})
    # get positions of frags in reference
    positions = find_Cx_annulirostris_frag_position_in_ref(msa_path, reference_path, reference_contig, 31, tmp_dir) # will only work if no gaps in the msa at start or end
    start = positions["start"]["start"]
    end = positions["end"]["end"]
    # remove subtypes to ignore from the metadata table and the sequence matrix and ids list
    if ignore_clusters is not None:
        fragment_metadata = fragment_metadata.filter(~pl.col("subtype").is_in(ignore_clusters))
        ids_to_keep = fragment_metadata["fasta_id"].to_list() + [f"{reference_contig}"] # make sure to keep the reference sequence in the MSA
        indices_to_keep = [ids.index(id) for id in ids if id in ids_to_keep]
        seq_matrix = seq_matrix[indices_to_keep, :]
        ids = [ids[i] for i in indices_to_keep]
    # final dataframe to hold subtype defining SNPs
    results = None
    for subtype in fragment_metadata["subtype"].unique():
        # get genbank ids from the metadata table
        subtype_ids = fragment_metadata.filter(pl.col("subtype") == subtype)["fasta_id"].to_list()
        # find positions where all sequences for this subtype are the same and different from the other sequences.
        differences_df = find_differences_between_subtype_and_all_others(subtype_ids, ids, f"{reference_contig}", seq_matrix)
        if differences_df.shape[0] == 0:
            continue # if there are no differences between this subtype and all others, move on
        differences_df = differences_df.with_columns(
            pl.lit(subtype).alias("subtype"),
            (pl.col("position") + start).alias("position_in_reference")
            )
        # concatenate the differences dataframe for this subtype with the results dataframe for all subtypes
        if results is None:
            results = differences_df
        else:
            results = pl.concat([results, differences_df], how="vertical")
    return results

def merge_cluster_defining_snps(files_to_merge: list, focal_subtype: str, output_file: str) -> None:
    focal_subtype = str(focal_subtype)
    dfs = []
    subtypes = set()
    for file in files_to_merge:
        df = pl.read_csv(file, separator='\t')
        df = df.with_columns(pl.col("subtype").cast(pl.String))
        dfs.append(df)
        subtypes_in_df = df["subtype"].unique().to_list()
        assert focal_subtype in subtypes_in_df
        subtypes.update(subtypes_in_df)
    non_focal_subtypes = [i for i in subtypes if i != focal_subtype]
    joined_df = None
    for i, df in enumerate(dfs):
        df = df.filter(pl.col("subtype") == focal_subtype)
        if joined_df is None:
            joined_df = df
        else:
            joined_df = joined_df.join(df, on=["position_in_reference", "ref_base", "subtype_base"], how="inner", suffix=f"_other{i}")
    # combine non_subtype_bases columns from different dataframes into one column
    non_subtype_bases_cols = [col for col in joined_df.columns if col.startswith("non_subtype_bases")]
    joined_df = joined_df.with_columns(
        pl.concat_list(non_subtype_bases_cols).map_elements(
            lambda x: get_set_of_bases_and_fix_multinucleotide_notation(x), 
            return_dtype=pl.String
        ).alias("final_non_subtype_bases")
    ).drop(non_subtype_bases_cols).rename({"final_non_subtype_bases": "non_subtype_bases"})
    # if subtype_base is a substring in non_subtype_bases, remove it from df
    joined_df = joined_df.filter(~pl.col("non_subtype_bases").str.contains(pl.col("subtype_base"), literal=True))
    # write the joined dataframe to a file
    joined_df.write_csv(output_file, separator='\t')

def get_set_of_bases_and_fix_multinucleotide_notation(bases_list: list) -> str:
    multinuc_notations = {
        "w": ["a", "t"],
        "y": ["c", "t"],
    }
    bases_set = []
    for bases_str in bases_list:
        for base in bases_str.split(","):
            base = base.lower().strip()
            if base in multinuc_notations:
                for b in multinuc_notations[base]:
                    bases_set.append(b)
            elif base:  # only add non-empty strings
                bases_set.append(base)
    return ",".join(sorted(set(bases_set)))